// src/pages/TicketDetail.js
import React, { useState, useEffect } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { useSelector } from "react-redux";
import api from "../api/axios";

const TicketDetail = () => {
  const { id } = useParams(); // ticket id from URL
  const { user } = useSelector((state) => state.auth);
  const navigate = useNavigate();

  const [ticket, setTicket] = useState(null);
  const [users, setUsers] = useState([]); // for assigned_to dropdown
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [isEditing, setIsEditing] = useState(false);

  // Editable fields (only for admin)
  const [editForm, setEditForm] = useState({
    status: "",
    assigned_to: "",
    confidential_notes: "",
  });

  useEffect(() => {
    const fetchTicket = async () => {
      try {
        const res = await api.get(`/tickets/${id}/`);
        setTicket(res.data);
        setEditForm({
          status: res.data.status || "",
          assigned_to: res.data.assigned_to || "",
          confidential_notes: res.data.confidential_notes || "",
        });
      } catch (err) {
        setError("Failed to load ticket.");
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    // Only admins need the user list for assignment
    if (user?.is_staff) {
      const fetchUsers = async () => {
        try {
          const res = await api.get("/auth/users/"); // Adjust endpoint if needed
          setUsers(res.data);
        } catch (err) {
          console.error("Failed to load users:", err);
        }
      };
      fetchUsers();
    }

    fetchTicket();
  }, [id, user]);

  const handleSave = async () => {
    try {
      const updateData = new FormData();
      if (editForm.status !== ticket.status) updateData.append("status", editForm.status);
      if (editForm.assigned_to !== ticket.assigned_to) updateData.append("assigned_to", editForm.assigned_to || "");
      if (editForm.confidential_notes !== ticket.confidential_notes)
        updateData.append("confidential_notes", editForm.confidential_notes);

      if ([...updateData.entries()].length === 0) {
        setIsEditing(false);
        return;
      }

      const res = await api.patch(`/tickets/${id}/`, updateData);
      setTicket(res.data);
      setIsEditing(false);
      alert("Ticket updated successfully!");
    } catch (err) {
      alert("Failed to update ticket.");
      console.error(err);
    }
  };

  if (loading) return <div style={styles.loading}>Loading ticket...</div>;
  if (error) return <div style={styles.error}>{error}</div>;
  if (!ticket) return null;

  const isAdmin = user?.is_staff;

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h2>#{ticket.id} - {ticket.title}</h2>
        <div>
          <Link to="/employee" style={styles.backBtn}>← Back to Tickets</Link>
          {isAdmin && !isEditing && (
            <button onClick={() => setIsEditing(true)} style={styles.editBtn}>
              Edit Ticket
            </button>
          )}
        </div>
      </div>

      <div style={styles.card}>
        <p><strong>Description:</strong><br />{ticket.description}</p>

        <p><strong>Priority:</strong> <span style={getPriorityStyle(ticket.priority)}>{ticket.priority}</span></p>

        <p><strong>Created by:</strong> User #{ticket.creator} • {new Date(ticket.created_at).toLocaleDateString()}</p>

        {/* Admin-only editable fields */}
        {isAdmin && (
          <>
            <div style={styles.field}>
              <strong>Status:</strong>
              {isEditing ? (
                <select
                  value={editForm.status}
                  onChange={(e) => setEditForm({ ...editForm, status: e.target.value })}
                  style={styles.select}
                >
                  <option value="OPEN">Open</option>
                  <option value="IN_PROGRESS">In Progress</option>
                  <option value="RESOLVED">Resolved</option>
                  <option value="PARTIALLY_CLOSED">Partially Closed</option>
                </select>
              ) : (
                <span style={getStatusStyle(ticket.status)}>{ticket.status.replace("_", " ")}</span>
              )}
            </div>

            <div style={styles.field}>
              <strong>Assigned to:</strong>
              {isEditing ? (
                <select
                  value={editForm.assigned_to}
                  onChange={(e) => setEditForm({ ...editForm, assigned_to: e.target.value })}
                  style={styles.select}
                >
                  <option value="">Unassigned</option>
                  {users.map((u) => (
                    <option key={u.id} value={u.id}>
                      {u.email} (ID: {u.id})
                    </option>
                  ))}
                </select>
              ) : (
                <span>{ticket.assigned_to ? `User #${ticket.assigned_to}` : "Unassigned"}</span>
              )}
            </div>

            <div style={styles.field}>
              <strong>Confidential Notes (Admin Only):</strong>
              {isEditing ? (
                <textarea
                  value={editForm.confidential_notes}
                  onChange={(e) => setEditForm({ ...editForm, confidential_notes: e.target.value })}
                  rows="4"
                  style={styles.textarea}
                  placeholder="These notes are encrypted and visible only to admins..."
                />
              ) : (
                <p style={styles.confidential}>
                  {ticket.confidential_notes || <em>No confidential notes</em>}
                </p>
              )}
            </div>
          </>
        )}

        {/* Non-admin view */}
        {!isAdmin && (
          <>
            <p><strong>Status:</strong> <span style={getStatusStyle(ticket.status)}>{ticket.status.replace("_", " ")}</span></p>
            {ticket.assigned_to && <p><strong>Assigned to:</strong> User #{ticket.assigned_to}</p>}
          </>
        )}

        {isEditing && (
          <div style={styles.actions}>
            <button onClick={handleSave} style={styles.saveBtn}>Save Changes</button>
            <button onClick={() => setIsEditing(false)} style={styles.cancelBtn}>Cancel</button>
          </div>
        )}
      </div>

      {/* Audit Logs */}
      {ticket.audit_logs?.length > 0 && (
        <div style={styles.section}>
          <h3>Audit Log</h3>
          {ticket.audit_logs.map((log) => (
            <div key={log.id} style={styles.logEntry}>
              <small>{new Date(log.created_at).toLocaleString()}</small> • {log.created_by}: {log.message}
            </div>
          ))}
        </div>
      )}

      {/* Attachments */}
      {ticket.attachments?.length > 0 && (
        <div style={styles.section}>
          <h3>Attachments</h3>
          {ticket.attachments.map((att) => (
            <div key={att.id}>
              <a href={att.file} target="_blank" rel="noreferrer">{att.file.split('/').pop()}</a>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

const getPriorityStyle = (priority) => ({
  padding: "6px 12px",
  borderRadius: "20px",
  fontWeight: "bold",
  background: priority === "HIGH" ? "#ff4d4f" : priority === "MEDIUM" ? "#faad14" : "#52c41a",
  color: "white",
});

const getStatusStyle = (status) => ({
  padding: "6px 12px",
  borderRadius: "20px",
  fontWeight: "bold",
  background: status === "OPEN" ? "#1890ff" : status === "IN_PROGRESS" ? "#faad14" : status === "RESOLVED" ? "#52c41a" : "#9254de",
  color: "white",
});

